class Solution {
public:
    long long minSum(vector<int>& nums1, vector<int>& nums2) {
        long long s1 = 0, s2 = 0;
        int z1 = 0, z2 = 0;
        for (int x : nums1) {
            s1 += (x == 0 ? 1 : x);
            if (x == 0) z1++;
        }
        for (int x : nums2) {
            s2 += (x == 0 ? 1 : x);
            if (x == 0) z2++;
        }
        if (z1 == 0 && s1 < s2) return -1;
        if (z2 == 0 && s2 < s1) return -1;
        return max(s1, s2);
    }
};

class Solution {
    public long minSum(int[] nums1, int[] nums2) {
        long s1 = 0, s2 = 0;
        int z1 = 0, z2 = 0;
        for (int x : nums1) {
            s1 += (x == 0 ? 1 : x);
            if (x == 0) z1++;
        }
        for (int x : nums2) {
            s2 += (x == 0 ? 1 : x);
            if (x == 0) z2++;
        }
        if (z1 == 0 && s1 < s2) return -1;
        if (z2 == 0 && s2 < s1) return -1;
        return Math.max(s1, s2);
    }
}

